#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

/**
 * The goal of this program is to find the Maximum Subarray Sum.
 * The original implementation used O(n^3) brute force.
 * This optimized version uses Kadane's Algorithm, which runs in O(n) time.
 */

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(NULL);

    int n;
    if (!(std::cin >> n) || n <= 0) {
        return 0;
    }

    long long current_max = 0;
    long long global_max = LLONG_MIN;

    for (int i = 0; i < n; ++i) {
        int val;
        std::cin >> val;

        if (i == 0) {
            current_max = val;
            global_max = val;
        } else {
            current_max = std::max((long long)val, current_max + val);
            global_max = std::max(global_max, current_max);
        }
    }

    std::cout << global_max << std::endl;

    return 0;
}

